package nl.timtoys.corruptedadventure.registry;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.levelgen.feature.ConfiguredFeature;
import nl.timtoys.corruptedadventure.CorruptedAdventure;

/**
 * Keys of the mod's configured features. The features themselves are datapack entries, generated by datagen.
 */
public final class ModConfiguredFeatures {
    // Withered expanse (transition 1→2). The dead trees are bare trunks, usable anywhere on #dirt.
    public static final ResourceKey<ConfiguredFeature<?, ?>> DEAD_TREE = key("dead_tree");
    public static final ResourceKey<ConfiguredFeature<?, ?>> DEAD_TREE_FORKED = key("dead_tree_forked");
    public static final ResourceKey<ConfiguredFeature<?, ?>> WITHERED_TREES = key("withered_trees");
    public static final ResourceKey<ConfiguredFeature<?, ?>> WITHERED_VEGETATION = key("withered_vegetation");
    public static final ResourceKey<ConfiguredFeature<?, ?>> WITHERED_SANDSTONE_ROCK = key("withered_sandstone_rock");
    public static final ResourceKey<ConfiguredFeature<?, ?>> WITHERED_SAND_PATCH = key("withered_sand_patch");
    // Ring 1 horror features.
    public static final ResourceKey<ConfiguredFeature<?, ?>> BARE_PATCH = key("bare_patch");
    public static final ResourceKey<ConfiguredFeature<?, ?>> UNNATURAL_TUNNEL = key("unnatural_tunnel");

    private ModConfiguredFeatures() {
    }

    private static ResourceKey<ConfiguredFeature<?, ?>> key(String path) {
        return ResourceKey.create(Registries.CONFIGURED_FEATURE, CorruptedAdventure.id(path));
    }
}
